mapper.sql:
WHERE 1=1

  AND (UPPER(T1.APP_ID) LIKE '%'||UPPER(#{keyword})||'%'
    OR UPPER(T1.APP_NAME) LIKE '%'||UPPER(#{keyword})||'%'
    OR UPPER(NVL(T1.SYSTEM_ID,'')) LIKE '%'||UPPER(#{keyword})||'%')

AND T1.APP_ID = #{appId}
AND T1.APP_NAME LIKE '%'||#{appName}||'%'
AND T1.SYSTEM_ID = #{systemId}
AND T1.STATUS_CD = #{statusCd}

mapper.select:
SELECT * FROM (
  SELECT a.*, ROWNUM rnum FROM (
    SELECT T1.APP_ID, T1.APP_NAME, T1.SYSTEM_ID, T1.LANG_CD, T1.STATUS_CD, T1.REMARK,
           T1.REG_USER_ID, T1.REG_DTM, T1.CHG_USER_ID, T1.CHG_DTM
      FROM TB_IF_APPLICATION_PILOT T1

     ORDER BY T1.REG_DTM DESC, T1.APP_ID ASC
  ) a WHERE ROWNUM <= #{offset} + #{pageSize}
) WHERE rnum > #{offset}

mapper.update:
UPDATE TB_IF_APPLICATION_PILOT SET APP_NAME=#{appName}, SYSTEM_ID=#{systemId}, LANG_CD=#{langCd},
  STATUS_CD=#{statusCd}, REMARK=#{remark}, CHG_USER_ID=#{chgUserId}, CHG_DTM=#{chgDtm}
 WHERE APP_ID=#{appId}
